namespace ghidra.app.plugin.core.diff;

using docking;
using docking.action;
using docking.action;
using ghidra.program.util;

public class DiffMergeAllAction : DockingAction {
	
	private static string ACTION_NAME = "Set Merge for All Apply Settings";
	private static string GROUP_NAME = "DIFF_APPLY_ACTION";
	private static string DESCRIPTION = "Change all the difference type apply settings to Merge if possible. Otherwise, change to Replace.";
	private static string[] popupPath = new string[] { ACTION_NAME };
	private static string[] menuPath = new string[] { ACTION_NAME };
	private DiffApplySettingsProvider provider;

	/**
	 * @param provider the provider using this action
	 */
	public DiffMergeAllAction(DiffApplySettingsProvider provider) : base("Set All To Merge", provider.getPlugin().getName())
    {
		this.provider = provider;
		setMenuBarData( new MenuData( menuPath, GROUP_NAME ) );
		setPopupMenuData( new MenuData( popupPath, GROUP_NAME ) );
		setDescription(DESCRIPTION);
	}

	/* @Override */
    public void actionPerformed(ActionContext context) {
		provider.setApplyFilter(new ProgramMergeFilter(ProgramMergeFilter.ALL, ProgramMergeFilter.MERGE));
	}

}
